/**
 * @param {number} n
 * @return {number}
 */
var sumAndMultiply = function(n) {
    let x = 0;
    let sum = 0;
    let count = 0;

    while (n > 0) {
        const rem = n % 10;
        if (rem > 0) {
            x += rem * Math.pow(10, count);
            sum += rem;
            count++;
        }
        n = Math.floor(n / 10);
    }

    return x * sum;
};
